SELECT u.user_id, u.username, u.portrait, u.nickname, u.signature, u.address
FROM user u
INNER JOIN friend f ON u.user_id = f.to_user_id
WHERE f.from_user_id = #{userId} AND f.status = #{status}
ORDER BY f.friend_id DESC
LIMIT #{offset}, #{pageSize}

SELECT u.user_id, u.username, u.portrait, u.nickname, u.signature, u.address
FROM user u
INNER JOIN friend f ON u.user_id = f.to_user_id
WHERE f.from_user_id = #{userId} AND f.group_id = #{groupId}
ORDER BY f.friend_id DESC
LIMIT #{offset}, #{pageSize}
